ROOT=[dict(id='C0690',meaning='光；照亮',core='lumin-：光；从真实照明走到“让人明白”和“杰出人物”的比喻。',image='光源照到桌面，眼睛看见表面；一个人的思想也像灯一样让问题清楚。',intro='拉丁 lumen 的词干是 lumin-。常用词 illuminate、illumination 连接照明与理解；luminous 描写明亮；luminary 用光源比喻杰出人物。科学词会把光分成不同问题：光量、落到表面的光、朝观察方向的亮度，以及发光机制。',forms='lumen 与 lumin- 是拉丁词形变化；il- 是 in- 在 l 前的形式。luminescence、luminance 等是近代术语，不能都画成古代已有的完整词。',branches=[['照亮与说明白','illuminate、illumination、luminous'],['明亮与计量','lumen、luminosity、luminance、illuminance'],['发光机制','luminescence、luminescent、bioluminescence、bioluminescent'],['发光者的比喻','luminary']],contrasts='流明 lumen 是光通量单位；illuminance 是表面收到的照度；luminance 是从指定方向看的光度学亮度；天文学 luminosity 说天体本身的辐射功率。lumen 的管腔义另承“开口”意义。',practice='用台灯、桌面和屏幕分别解释 lumen、illuminance、luminance，再说明 luminous 与 luminescent 为什么不能处处互换。',words=[w for w in family if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/lumen','https://www.nist.gov/programs-projects/photometry','https://www.etymonline.com/word/luminary','https://goldbook.iupac.org/terms/view/L03641'])]
assert keep==set(family)-set(excluded)
assert all(w['word']in m['owned_words']for w in W)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history']),w['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_143_lumin.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0690',len(W),'new',sum(len(w['examples'])for w in W),'examples')
